inputs = ['xabyhy', 'hya', 'fjuh', 'giy', 'ywaxbb']
outputs = ['xabyhy', 'hya', 'fwjuh', 'gaaey', 'ywaxbb']

print("Input -> Output:")
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"{inp} -> {outp}")

print("\nCharacter-by-character analysis:")
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"\n{inp} -> {outp}")
    if len(inp) == len(outp):
        for j, (char_in, char_out) in enumerate(zip(inp, outp)):
            if char_in != char_out:
                print(f"  Position {j}: '{char_in}' -> '{char_out}'")
    else:
        print(f"  Length change: {len(inp)} -> {len(outp)}")

